"""Install native engines into runners generated by `flutter create`.

The source in platform/ is canonical. Re-running this installer deliberately
replaces MainActivity and AppDelegate; it preserves other runner configuration.
"""
from pathlib import Path
import plistlib
import re
import sys
import xml.etree.ElementTree as ET


MEDIA3 = '''
// FRAMEFORGE_MEDIA3_START
dependencies {
    implementation("androidx.media3:media3-transformer:1.5.1")
    implementation("androidx.media3:media3-effect:1.5.1")
    implementation("androidx.media3:media3-common:1.5.1")
}
// Align playback and export; Media3's UnstableApi requires a consistent version.
configurations.all {
    resolutionStrategy.eachDependency {
        if (requested.group == "androidx.media3") {
            useVersion("1.5.1")
        }
    }
}
// FRAMEFORGE_MEDIA3_END
'''

PODFILE = '''platform :ios, '15.0'
ENV['COCOAPODS_DISABLE_STATS'] = 'true'
project 'Runner', { 'Debug' => :debug, 'Profile' => :release, 'Release' => :release }
def flutter_root
  generated_xcode_build_settings_path = File.expand_path(File.join('..', 'Flutter', 'Generated.xcconfig'), __FILE__)
  raise "Run flutter pub get first" unless File.exist?(generated_xcode_build_settings_path)
  File.foreach(generated_xcode_build_settings_path) do |line|
    matches = line.match(/FLUTTER_ROOT\\=(.*)/)
    return matches[1].strip if matches
  end
  raise "FLUTTER_ROOT not found"
end
require File.expand_path(File.join('packages', 'flutter_tools', 'bin', 'podhelper'), flutter_root)
flutter_ios_podfile_setup
target 'Runner' do
  use_frameworks!
  flutter_install_all_ios_pods File.dirname(File.realpath(__FILE__))
  target 'RunnerTests' do
    inherit! :search_paths
  end
end
post_install do |installer|
  installer.pods_project.targets.each do |target|
    flutter_additional_ios_build_settings(target)
    target.build_configurations.each do |config|
      config.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = '15.0'
    end
  end
end
'''


def install(root: Path) -> None:
    app = root / 'android/app'
    gradle = app / 'build.gradle.kts'
    if not gradle.is_file():
        raise RuntimeError('Expected Kotlin Gradle runners from Flutter 3.35+. Run tool/setup.sh.')
    text = gradle.read_text()
    text, changed = re.subn(r'minSdk\s*=\s*(?:flutter\.minSdkVersion|\d+)', 'minSdk = 26', text)
    if not changed:
        raise RuntimeError('Could not find Android minSdk configuration.')
    text = re.sub(r'\n// FRAMEFORGE_MEDIA3_START.*?// FRAMEFORGE_MEDIA3_END\n?', '', text, flags=re.S)
    gradle.write_text(text.rstrip() + '\n' + MEDIA3)
    kotlin = app / 'src/main/kotlin/dev/frameforge/frameforge'
    kotlin.mkdir(parents=True, exist_ok=True)
    for filename in ('MainActivity.kt', 'VideoEngine.kt'):
        (kotlin / filename).write_text((root / 'platform/android' / filename).read_text())
    manifest = app / 'src/main/AndroidManifest.xml'
    if not manifest.is_file():
        raise RuntimeError('Missing generated Android manifest.')
    android_ns = 'http://schemas.android.com/apk/res/android'
    ET.register_namespace('android', android_ns)
    ET.register_namespace('tools', 'http://schemas.android.com/tools')
    attribute = lambda name: '{' + android_ns + '}' + name
    tree = ET.parse(manifest)
    document = tree.getroot()
    application = document.find('application')
    if application is None:
        raise RuntimeError('Missing Android application configuration.')
    application.set(attribute('label'), 'FrameForge')
    # flutter_web_auth_2 documents that generated taskAffinity settings can
    # disrupt Android browser callbacks; the Flutter activity uses singleTop.
    application.attrib.pop(attribute('taskAffinity'), None)
    for activity in application.findall('activity'):
        activity.attrib.pop(attribute('taskAffinity'), None)
        if activity.get(attribute('name'), '').endswith('MainActivity'):
            activity.set(attribute('launchMode'), 'singleTop')
    if not any(permission.get(attribute('name')) == 'android.permission.INTERNET' for permission in document.findall('uses-permission')):
        document.insert(0, ET.Element('uses-permission', {attribute('name'): 'android.permission.INTERNET'}))
    callback_name = 'com.linusu.flutter_web_auth_2.CallbackActivity'
    for activity in list(application.findall('activity')):
        if activity.get(attribute('name')) == callback_name:
            application.remove(activity)
    callback = ET.SubElement(application, 'activity', {attribute('name'): callback_name, attribute('exported'): 'true'})
    intent = ET.SubElement(callback, 'intent-filter')
    ET.SubElement(intent, 'action', {attribute('name'): 'android.intent.action.VIEW'})
    for category in ('DEFAULT', 'BROWSABLE'):
        ET.SubElement(intent, 'category', {attribute('name'): 'android.intent.category.' + category})
    ET.SubElement(intent, 'data', {attribute('scheme'): 'frameforge-ai'})
    ET.indent(tree, space='    ')
    tree.write(manifest, encoding='unicode')

    runner = root / 'ios/Runner'
    # Both classes are in a file already registered in the generated Xcode project.
    # This avoids a fragile edit of PBX source-file references.
    delegate = (root / 'platform/ios/AppDelegate.swift').read_text()
    engine = (root / 'platform/ios/VideoEngine.swift').read_text()
    (runner / 'AppDelegate.swift').write_text(delegate + '\n' + engine)
    info = runner / 'Info.plist'
    with info.open('rb') as handle:
        values = plistlib.load(handle)
    values['CFBundleDisplayName'] = 'FrameForge'
    values['CFBundleName'] = 'FrameForge'
    url_types = values.setdefault('CFBundleURLTypes', [])
    if not any('frameforge-ai' in value.get('CFBundleURLSchemes', []) for value in url_types):
        url_types.append({'CFBundleURLName': 'dev.frameforge.ai-login', 'CFBundleURLSchemes': ['frameforge-ai']})
    # Native registration uses the classic FlutterAppDelegate lifecycle.
    # UIKit still supports it; keep generated UIScene settings from bypassing it.
    values.pop('UIApplicationSceneManifest', None)
    with info.open('wb') as handle:
        plistlib.dump(values, handle, sort_keys=False)
    pbx = root / 'ios/Runner.xcodeproj/project.pbxproj'
    if not pbx.is_file():
        raise RuntimeError('Missing generated Xcode project.')
    pbx.write_text(re.sub(r'IPHONEOS_DEPLOYMENT_TARGET = [\d.]+;',
        'IPHONEOS_DEPLOYMENT_TARGET = 15.0;', pbx.read_text()))
    podfile = root / 'ios/Podfile'
    if not podfile.exists():
        podfile.write_text(PODFILE)
    else:
        body = podfile.read_text()
        body, changed = re.subn(r"^\s*#?\s*platform :ios, '[\d.]+'", "platform :ios, '15.0'", body, flags=re.M)
        if not changed:
            body = "platform :ios, '15.0'\n" + body
        podfile.write_text(body)


if __name__ == '__main__':
    try:
        install(Path(__file__).resolve().parents[1])
    except (OSError, ValueError, RuntimeError) as exc:
        sys.exit(f'Could not install mobile engines: {exc}')
    print('Installed Android Media3 and iOS AVFoundation video engines.')
